package example.transportlab;
import java.util.*;
import java.nio.*;
import java.nio.charset.*;

// Native JVM/Android counterpart of the experimental signal receiver.
public final class Signal {
 public static final class Action {long cls,type,generation;byte[] payload;Action(long c,long t,byte[] p,long g){cls=c;type=t;payload=p;generation=g;}}
 final Wire.Identity self,peer;final byte[] connection;final long use;
 long leaseUntil,authorizationRevision=1;boolean membersAuthorized=true;
 long generation=1,next=1,gapDeadline;boolean bootReady,localSDP,remoteSDP,dtls,confirmed,closed,retired,ended;
 Wire.Opened challenge,probe,receivedProbe;long clock,roundDeadline;int dispatches;final Map<String,byte[]> allowed=new HashMap<>(),dispatched=new HashMap<>();
 byte[] localHash={},remoteHash={},localFingerprint={},remoteFingerprint={},remoteUfrag={},remoteMid={};
 int candidates,batches,sdkActions,duplicates,conflicts,rejected,unsupported,staleChallenges;
 final Map<String,byte[]> seen=new HashMap<>();final Map<String,Long> cacheUntil=new HashMap<>();final Map<Long,Wire.Opened> pending=new HashMap<>();final Map<Long,Long> pendingAt=new HashMap<>();
 public Signal(Wire.Identity self,Wire.Identity peer,byte[] connection,long use,long now){this.self=self;this.peer=Wire.member(peer);clock=now;roundDeadline=now+10000;leaseUntil=roundDeadline;this.connection=connection;this.use=use;}
 synchronized void rememberProbe(Wire.Opened sent)throws Exception{Wire.check(!closed&&authorized());sent=Wire.openSent(sent.raw,self,peer,clock);preflight(sent);Wire.Context c=sent.ctx;Wire.check(sent.type==1&&c.cls==1&&Arrays.equals(c.domain,Wire.utf8("bootstrap"))&&c.generation==0&&c.use==0&&clock<c.deadline&&Arrays.equals(c.from,self.id)&&Arrays.equals(c.to,peer.id)&&Arrays.equals(c.connection,connection)&&Arrays.equals(c.senderBoot,self.boot)&&Arrays.equals(c.senderInstance,self.instance));probe=freeze(sent);}
 static Wire.Opened freeze(Wire.Opened o){Wire.Opened copy=new Wire.Opened();copy.ctx=Wire.context(o.ctx.encode());copy.type=o.type;copy.hash=o.hash.clone();copy.raw=o.raw.clone();copy.payload=o.payload.clone();return copy;}
 synchronized void rememberChallenge(Wire.Opened sent)throws Exception{Wire.check(!closed&&authorized());sent=Wire.openSent(sent.raw,self,peer,clock);preflight(sent);Wire.Context c=sent.ctx;Map<Integer,Wire.Field> f=Schema.fields(sent.payload,"Challenge");Wire.need(f,"bbbbub");Wire.check(receivedProbe!=null&&clock<receivedProbe.ctx.deadline&&Arrays.equals(f.get(6).b,receivedProbe.hash)&&sent.type==2&&c.recipientUnknown==0&&c.cls==1&&Arrays.equals(c.domain,Wire.utf8("bootstrap"))&&c.generation==0&&c.use==0&&clock<c.deadline&&sent.hash.length==32&&Arrays.equals(c.from,self.id)&&Arrays.equals(c.to,peer.id)&&Arrays.equals(c.connection,connection)&&Arrays.equals(c.senderBoot,self.boot)&&Arrays.equals(c.receiverBoot,peer.boot)&&Arrays.equals(c.senderInstance,self.instance)&&Arrays.equals(c.receiverInstance,peer.instance));challenge=freeze(sent);}
 void acceptACK(Wire.Opened ack){byte[] raw=ack.payload;Map<Integer,Wire.Field> f=Schema.fields(raw,"Ack");Wire.check(f.size()==7&&f.get(1).b.length==0&&f.get(2).u==0&&!f.containsKey(3));for(int n:new int[]{4,5,7,8})Wire.check(f.containsKey(n)&&!f.get(n).bytes);Wire.check(f.containsKey(6)&&f.get(6).bytes&&f.get(6).b.length==32&&f.get(4).u>=1&&f.get(4).u<=2&&f.get(5).u!=0&&Long.compareUnsigned(f.get(8).u,2)<=0);
  if(challenge==null){Wire.check(f.get(7).u!=0||(f.get(4).u==1&&f.get(8).u==0));return;}
  if(f.get(7).u==0||(challenge!=null&&Arrays.equals(f.get(6).b,challenge.hash))){Wire.check(challenge!=null);Wire.check(clock<challenge.ctx.deadline);Wire.Context c=challenge.ctx,a=ack.ctx;Wire.check(Arrays.equals(a.from,c.to)&&Arrays.equals(a.to,c.from)&&Arrays.equals(a.connection,c.connection)&&Arrays.equals(a.senderBoot,c.receiverBoot)&&Arrays.equals(a.receiverBoot,c.senderBoot)&&Arrays.equals(a.senderInstance,c.receiverInstance)&&Arrays.equals(a.receiverInstance,c.senderInstance));Wire.check(f.get(4).u==c.cls&&f.get(5).u==c.seq&&Arrays.equals(f.get(6).b,challenge.hash)&&f.get(7).u==c.generation&&f.get(8).u==c.use);bootReady=true;}else Wire.check(bootReady);
 }
 void preflight(Wire.Opened o)throws Exception{o.payload=Schema.known(o.ctx.cls,o.type,o.payload);if(o.ctx.cls!=1)return;
 if(o.type==1||o.type==2){Map<Integer,Wire.Field> f=Schema.fields(o.payload,o.type==1?"Probe":"Challenge");Wire.Context c=o.ctx;Wire.check(Arrays.equals(f.get(1).b,c.connection)&&Arrays.equals(f.get(2).b,c.senderInstance)&&Arrays.equals(f.get(3).b,c.senderBoot)&&(o.type!=2||Arrays.equals(f.get(4).b,c.receiverBoot)));}
 if(o.type==3||o.type==4){Map<Integer,Wire.Field> f=Schema.fields(o.payload,"SDP");Wire.check(Arrays.equals(Wire.hash(f.get(1).b),f.get(2).b));info(f.get(1).b);}
 if(o.type==5){Wire.Reader r=new Wire.Reader(o.payload);int count=0;while(r.at<o.payload.length&&o.payload[r.at]==10){r.at++;int n=(int)r.uint();Map<Integer,Wire.Field> f=Schema.fields(Arrays.copyOfRange(o.payload,r.at,r.at+n),"Candidate");r.at+=n;String original=text(f.get(1).b);Wire.check(original.startsWith("candidate:"));for(byte b:f.get(1).b)Wire.check((b&255)>=32&&(b&255)<=126);String[] t=original.trim().split(" +");int u=0;for(int i=0;i<t.length;i++)if(t[i].equalsIgnoreCase("ufrag"))Wire.check(t[i].equals("ufrag")&&++u==1&&i+1<t.length&&t[i+1].equals(text(f.get(2).b)));Wire.check(f.get(2).b.length>=4&&f.get(2).b.length<=256&&f.get(3).b.length>0&&f.get(4).u==0&&f.get(5).u==o.ctx.generation);count++;}Map<Integer,Wire.Field> f=Wire.parse(Arrays.copyOfRange(o.payload,r.at,o.payload.length),1);Wire.check(count>0&&f.get(2).u<=3);}
 if(o.type==6){Map<Integer,Wire.Field> f=Schema.fields(o.payload,"EndCandidates");Wire.check(f.get(1).b.length>=4&&f.get(2).u<=64&&f.get(3).u<=4);}
 if(o.type==7)for(Wire.Field f:Schema.fields(o.payload,"Confirm").values())Wire.check(f.b.length==32);
 if(o.type==8){Map<Long,Long> t=Schema.restart(o.payload);Wire.check(offerer()&&o.ctx.use==use&&o.ctx.generation==generation&&t.size()==1&&Objects.equals(t.get(use),generation));}
 }
 synchronized void setAuthorization(long until,boolean members,long revision){leaseUntil=until;membersAuthorized=members;authorizationRevision=revision;}
 boolean authorized(){return clock<leaseUntil&&membersAuthorized&&authorizationRevision==1;}
 synchronized boolean replyAllowed(byte[] raw,long now){tick(now);if(closed||!authorized())return false;try{Wire.Opened o=Wire.open(raw,peer,self,clock);preflight(o);Wire.Context c=o.ctx;return Arrays.equals(c.connection,connection)&&Arrays.equals(seen.get(key(c)),o.hash)&&(c.generation==0||c.generation==generation)&&!(c.cls==2&&(o.type==4||o.type==10||o.type==11||o.type==12||o.type==13));}catch(Exception e){return false;}}
 boolean offerer(){return Wire.compare(self.id,peer.id)<0;}
 boolean ready(){return !closed&&localSDP&&remoteSDP&&dtls&&confirmed;}
 static String key(Wire.Context c){return Wire.hex(c.from)+"/"+Wire.hex(c.senderInstance)+"/"+Wire.hex(c.connection)+"/"+Long.toUnsignedString(c.use)+"/"+Long.toUnsignedString(c.generation)+"/"+c.cls+"/"+Long.toUnsignedString(c.seq);}
 static String text(byte[] b)throws Exception{return StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(b)).toString();}
 static byte[][] info(byte[] raw)throws Exception{SDPCheck.validate(raw);byte[] uf={},mid={},fp={};for(String line:text(raw).split("\r\n")){if(line.startsWith("a=ice-ufrag:"))uf=Wire.utf8(line.substring(12));if(line.startsWith("a=mid:"))mid=Wire.utf8(line.substring(6));if(line.startsWith("a=fingerprint:sha-256 "))fp=Wire.unhex(line.substring("a=fingerprint:sha-256 ".length()).replace(":",""));}return new byte[][]{uf,mid,fp};}
 synchronized void setLocal(byte[] raw,boolean offer,long gen)throws Exception{Wire.check(authorized()&&clock<roundDeadline&&gen==generation&&!closed&&bootReady&&offer==offerer()&&(!offer||!localSDP)&&(offer||remoteSDP));byte[][] meta=info(raw);localSDP=true;localHash=Wire.hash(raw);localFingerprint=meta[2];}
 synchronized void nextGeneration(long gen){Wire.check(clock<roundDeadline&&(!closed||retired)&&gen==generation+1&&gen!=0);generation=gen;next=1;closed=retired=false;localSDP=remoteSDP=dtls=confirmed=ended=false;pending.clear();pendingAt.clear();allowed.clear();dispatched.clear();gapDeadline=0;candidates=batches=0;}
 static byte[] sdpBody(byte[] raw){return Wire.pb(Wire.b(1,raw),Wire.b(2,Wire.hash(raw)));}
 void remember(Wire.Opened o){String k=key(o.ctx);seen.put(k,o.hash);cacheUntil.put(k,o.ctx.deadline+300000);}
 synchronized List<Action> receive(byte[] raw,long now)throws Exception{try{tick(now);return accept(Wire.open(raw.clone(),peer,self,clock),clock);}catch(Exception e){rejected++;throw e;}}
 synchronized List<Action> accept(Wire.Opened o,long now)throws Exception{
  tick(now);o=Wire.open(o.raw,peer,self,clock);Wire.check(authorized()&&clock<roundDeadline);Wire.Context c=o.ctx;Wire.check(Arrays.equals(c.connection,connection)&&Arrays.equals(c.from,peer.id));preflight(o);String k=key(c);
  if(seen.containsKey(k)){if(!Arrays.equals(seen.get(k),o.hash)){conflicts++;throw new IllegalArgumentException("conflict");}duplicates++;return Collections.emptyList();}Wire.check((!closed||retired)&&seen.size()<2048);
  if(c.cls==2){if(o.type==4)acceptACK(o);remember(o);if(o.type!=4&&o.type!=10){unsupported++;return Arrays.asList(new Action(2,10,Wire.pb(Wire.u(1,c.cls),Wire.u(2,o.type),Wire.u(3,c.seq),Wire.b(4,o.hash)),c.generation));}return Arrays.asList(new Action(2,o.type,o.payload,c.generation));}
  if(o.type==1||o.type==2){Wire.check(Arrays.equals(c.domain,Wire.utf8("bootstrap"))&&c.generation==0&&c.use==0);Map<Integer,Wire.Field> f=Schema.fields(o.payload,o.type==1?"Probe":"Challenge");Wire.need(f,o.type==1?"bbb":"bbbbub");Wire.check(Arrays.equals(f.get(1).b,c.connection)&&Arrays.equals(f.get(2).b,c.senderInstance)&&Arrays.equals(f.get(3).b,c.senderBoot));if(o.type==2&&probe!=null)Wire.openSent(probe.raw,self,peer,clock);if(o.type==2)Wire.check(Long.compareUnsigned(f.get(5).u,1)<=0&&f.get(6).b.length==32&&probe!=null&&clock<probe.ctx.deadline&&Arrays.equals(f.get(6).b,probe.hash)&&Arrays.equals(f.get(4).b,self.boot));if(peer.boot.length>0&&(!Arrays.equals(peer.boot,c.senderBoot)||!Arrays.equals(peer.instance,c.senderInstance))){retire(false);throw new IllegalArgumentException("new peer connection");}if(o.type==1)receivedProbe=freeze(o);peer.instance=c.senderInstance.clone();peer.boot=c.senderBoot.clone();remember(o);if(o.type==2){bootReady=true;if(f.get(5).u==1)staleChallenges++;}return Arrays.asList(new Action(1,o.type,o.payload,0));}
  if(!bootReady&&!closed&&!offerer()&&o.type==3&&c.cls==1&&Arrays.equals(c.domain,Wire.utf8("signal"))&&c.use==use&&c.generation==generation&&c.seq==1&&Arrays.equals(c.receiverBoot,self.boot)&&Arrays.equals(c.senderBoot,peer.boot)&&Arrays.equals(c.receiverInstance,self.instance)&&Arrays.equals(c.senderInstance,peer.instance)){Map<Integer,Wire.Field> f=Schema.fields(o.payload,"SDP");Wire.need(f,"bb");Wire.check(Arrays.equals(Wire.hash(f.get(1).b),f.get(2).b));info(f.get(1).b);bootReady=true;}
  Wire.check((!closed||(retired&&c.generation==generation+1))&&bootReady&&c.use==use&&Long.compareUnsigned(c.generation,generation)>=0&&Long.compareUnsigned(c.generation,generation+1)<=0);
  if(c.generation==generation+1){Wire.check(!offerer());nextGeneration(c.generation);}
  Wire.check(Long.compareUnsigned(c.seq,next)>=0);if(Long.compareUnsigned(c.seq,next)>0){Wire.check(pending.size()<32);remember(o);pending.put(c.seq,o);pendingAt.put(c.seq,now);refreshGap();return Collections.emptyList();}
  List<Action> actions=new ArrayList<>();for(;;){o=Wire.open(o.raw,peer,self,clock);Wire.check(!closed&&o.ctx.generation==generation&&o.ctx.use==use&&Arrays.equals(o.ctx.connection,connection));preflight(o);Action action=apply(o);remember(o);next++;if(action.type!=0){actions.add(action);if(action.cls==1&&action.type>=3&&action.type<=6)allowed.put(key(o.ctx),o.hash.clone());}if(!pending.containsKey(next))break;o=pending.remove(next);pendingAt.remove(next);}refreshGap();return actions;
 }
 Action apply(Wire.Opened o)throws Exception{
  Action action=new Action(1,o.type,o.payload,o.ctx.generation);
  switch((int)o.type){
   case 3:case 4:{Wire.check(o.type==3?(!offerer()&&!remoteSDP):(offerer()&&localSDP&&!remoteSDP));Map<Integer,Wire.Field> f=Schema.fields(o.payload,"SDP");Wire.need(f,"bb");Wire.check(Arrays.equals(Wire.hash(f.get(1).b),f.get(2).b));byte[][] m=info(f.get(1).b);remoteSDP=true;remoteHash=f.get(2).b;remoteUfrag=m[0];remoteMid=m[1];remoteFingerprint=m[2];sdkActions++;action.payload=f.get(1).b;break;}
   case 5:{Wire.check(remoteSDP&&!ended);Wire.Reader r=new Wire.Reader(o.payload);int count=0;while(r.at<o.payload.length&&o.payload[r.at]==10){r.at++;long size=r.uint();Wire.check(size>=0&&size<=1024&&size<=o.payload.length-r.at&&count<16);Map<Integer,Wire.Field> f=Schema.fields(Arrays.copyOfRange(o.payload,r.at,r.at+(int)size),"Candidate");r.at+=(int)size;Wire.need(f,"bbbuu");String original=text(f.get(1).b);Wire.check(original.startsWith("candidate:")&&!original.contains("\0")&&!original.contains("\r")&&!original.contains("\n"));for(byte v:f.get(1).b)Wire.check((v&255)>=32&&(v&255)<=126);String[] tokens=original.trim().split(" +");int ufrags=0;for(int i=0;i<tokens.length;i++)if(tokens[i].equalsIgnoreCase("ufrag")){Wire.check(tokens[i].equals("ufrag")&&++ufrags==1&&i+1<tokens.length&&tokens[i+1].equals(text(f.get(2).b)));}Wire.check(Arrays.equals(f.get(2).b,remoteUfrag)&&Arrays.equals(f.get(3).b,remoteMid)&&f.get(4).u==0&&f.get(5).u==generation);count++;}Map<Integer,Wire.Field> tail=Wire.parse(Arrays.copyOfRange(o.payload,r.at,o.payload.length),1);Wire.check(tail.size()==1&&tail.containsKey(2)&&!tail.get(2).bytes&&tail.get(2).u==batches&&count>0&&batches<4&&candidates+count<=64);candidates+=count;batches++;sdkActions+=count;break;}
   case 6:{Wire.check(remoteSDP&&!ended);Map<Integer,Wire.Field> f=Schema.fields(o.payload,"EndCandidates");Wire.need(f,"buu");Wire.check(Arrays.equals(f.get(1).b,remoteUfrag)&&f.get(2).u==candidates&&f.get(3).u==batches);sdkActions++;ended=true;break;}
   case 7:Wire.check(localSDP&&remoteSDP&&Arrays.equals(o.payload,confirmBody()));confirmed=true;break;
   case 8:Wire.check(offerer());break;
   case 9:closed=true;pending.clear();pendingAt.clear();allowed.clear();dispatched.clear();gapDeadline=0;break;
   default:unsupported++;action=new Action(2,10,Wire.pb(Wire.u(1,o.ctx.cls),Wire.u(2,o.type),Wire.u(3,o.ctx.seq),Wire.b(4,o.hash)),o.ctx.generation);
  }return action;
 }
 byte[] confirmBody(){return Wire.pb(Wire.b(1,offerer()?localHash:remoteHash),Wire.b(2,offerer()?remoteHash:localHash),Wire.b(3,offerer()?localFingerprint:remoteFingerprint),Wire.b(4,offerer()?remoteFingerprint:localFingerprint));}
 void refreshGap(){gapDeadline=0;for(Map.Entry<Long,Long> entry:pendingAt.entrySet()){long due=Math.min(entry.getValue()+2500,Math.min(pending.get(entry.getKey()).ctx.deadline,roundDeadline));if(gapDeadline==0||Long.compareUnsigned(due,gapDeadline)<0)gapDeadline=due;}}
 synchronized boolean tick(long now){clock=Math.max(clock,now);now=clock;if(now>=roundDeadline){retire(false);return true;}for(String k:new ArrayList<>(cacheUntil.keySet()))if(now>cacheUntil.get(k)){cacheUntil.remove(k);seen.remove(k);}if(gapDeadline!=0&&now>=gapDeadline){closed=retired=true;pending.clear();pendingAt.clear();allowed.clear();dispatched.clear();gapDeadline=0;return true;}return false;}
 synchronized void retire(boolean retry){closed=true;retired=retry;pending.clear();pendingAt.clear();allowed.clear();dispatched.clear();gapDeadline=0;}
 synchronized void forgetPeer(){peer.instance=new byte[0];peer.boot=new byte[0];retire(false);}
 synchronized boolean dispatch(byte[] raw,long now){tick(now);if(closed||!authorized())return false;try{Wire.Opened o=Wire.open(raw,peer,self,clock);String k=key(o.ctx);if(o.ctx.generation!=generation||o.ctx.use!=use||!Arrays.equals(o.ctx.connection,connection)||!Arrays.equals(allowed.get(k),o.hash)||dispatched.containsKey(k))return false;dispatched.put(k,o.hash.clone());dispatches++;return true;}catch(Exception e){return false;}}
}
